/**
 * @summary Найти кандидатов по одному фото ArcFace
 */
export const recognizeEmployeeQueryTopKDefault = 5;
export const recognizeEmployeeQueryTopKMax = 10;

export const recognizeEmployeeQueryThresholdDefault = 0.7;
export const recognizeEmployeeQueryThresholdMin = 0;
export const recognizeEmployeeQueryThresholdMax = 1;



export const RecognizeEmployeeQueryParams = zod.object({
  "top_k": zod.coerce.number().int().min(1).max(recognizeEmployeeQueryTopKMax).default(recognizeEmployeeQueryTopKDefault),
  "threshold": zod.coerce.number().min(recognizeEmployeeQueryThresholdMin).max(recognizeEmployeeQueryThresholdMax).default(recognizeEmployeeQueryThresholdDefault)
})

export const RecognizeEmployeeBody = zod.object({
  "file": zod.instanceof(Blob)
})

export const recognizeEmployeeResponseThresholdMin = 0;
export const recognizeEmployeeResponseThresholdMax = 1;

export const recognizeEmployeeResponseTopMatchOneCosineSimilarityMin = -1;
export const recognizeEmployeeResponseTopMatchOneCosineSimilarityMax = 1;

export const recognizeEmployeeResponseResultsItemCosineSimilarityMin = -1;
export const recognizeEmployeeResponseResultsItemCosineSimilarityMax = 1;



export const RecognizeEmployeeResponse = zod.object({
  "found": zod.boolean(),
  "threshold": zod.number().min(recognizeEmployeeResponseThresholdMin).max(recognizeEmployeeResponseThresholdMax),
  "top_match": zod.union([zod.object({
  "uuid": zod.string().uuid(),
  "cosine_similarity": zod.number().min(recognizeEmployeeResponseTopMatchOneCosineSimilarityMin).max(recognizeEmployeeResponseTopMatchOneCosineSimilarityMax),
  "employee_ref": zod.string().nullish(),
  "full_name": zod.string().nullish()
}),zod.null()]),
  "results": zod.array(zod.object({
  "uuid": zod.string().uuid(),
  "cosine_similarity": zod.number().min(recognizeEmployeeResponseResultsItemCosineSimilarityMin).max(recognizeEmployeeResponseResultsItemCosineSimilarityMax),
  "employee_ref": zod.string().nullish(),
  "full_name": zod.string().nullish()
})),
  "disclaimer": zod.string()
})


